import React from 'react';
import axios from 'axios';

//=========== STYLES OBJECT ===========//
const styles = {
  container: { maxWidth: '1200px', margin: '0 auto', padding: '24px' },
  header: { backgroundColor: '#004d40', color: 'white', padding: '24px' },
  headerLink: { color: 'white', textDecoration: 'none', marginRight: '24px' },
  section: { padding: '48px 24px' },
  h2: { fontSize: '2rem', fontWeight: 'bold', color: '#2d3748', marginBottom: '24px' },
  formGroup: { marginBottom: '24px' },
  label: { display: 'block', fontSize: '1.1rem', fontWeight: '500', color: '#4a5568', marginBottom: '4px' },
  input: { width: '100%', padding: '12px', border: '1px solid #cbd5e0', borderRadius: '6px', boxShadow: 'sm' },
  textarea: { width: '100%', padding: '12px', border: '1px solid #cbd5e0', borderRadius: '6px', boxShadow: 'sm' },
  button: { width: '100%', backgroundColor: '#0d9488', color: 'white', fontWeight: 'bold', padding: '12px 24px', borderRadius: '8px', border: 'none', cursor: 'pointer' },
  footer: { backgroundColor: '#2d3748', color: '#a0aec0', padding: '24px', textAlign: 'center' },
  footerLink: { color: '#a0aec0', textDecoration: 'none', margin: '0 12px' },
};

//=========== HEADER COMPONENT ===========//
const Header = () => (
  <header style={styles.header}>
    <div style={styles.container}>
      <h1 style={{ fontSize: '2.5rem', fontWeight: 'bold' }}>Dietitian Pradeepa's Clinic</h1>
      <p style={{ fontSize: '1.25rem', marginTop: '4px' }}>பரிபூரண ஆரோக்கியத்துடன் வாழ்க!</p>
      <nav style={{ marginTop: '16px' }}>
        <a href="#home" style={styles.headerLink}>Home</a>
        <a href="#about" style={styles.headerLink}>About Us</a>
        <a href="#services" style={styles.headerLink}>Services</a>
        <a href="#contact" style={styles.headerLink}>Contact Us</a>
      </nav>
    </div>
  </header>
);

//=========== HERO COMPONENT ===========//
const Hero = () => (
  <section style={{...styles.section, ...styles.container}}>
    <h2 style={{...styles.h2, marginBottom: '8px' }}>Getting to Know</h2>
    <h3 style={{...styles.h2, color: '#0d9488' }}>"Coimbatore Dietitian Pradeepa"</h3>
    <div style={{ color: '#4a5568', fontSize: '1.1rem', maxWidth: '800px' }}>
      <p><strong>Pradeepa Saravanan</strong> is a Coimbatore-based consultant Dietitian/Nutritionist...</p>
      <p style={{ marginTop: '16px' }}>She says, Diet is the cornerstone of health and vitality...</p>
      <button style={{...styles.button, width: 'auto', marginTop: '16px', backgroundColor: '#e2e8f0', color: '#2d3748' }}>
        How do you feel being a dietitian?
      </button>
    </div>
  </section>
);

//=========== APPOINTMENT FORM COMPONENT ===========//
const AppointmentForm = () => {
    const [formData, setFormData] = React.useState({ name: '', phone: '', date: '', message: '' });
    const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });
    const handleSubmit = async (e) => { e.preventDefault(); /* Axios logic here */ };

  return (
    <section style={{ ...styles.section, backgroundColor: '#f7fafc' }}>
      <div style={styles.container}>
        <h2 style={styles.h2}>Book an Appointment</h2>
        <form onSubmit={handleSubmit} style={{ maxWidth: '800px' }}>
          <div style={styles.formGroup}>
            <label htmlFor="name" style={styles.label}>Your Name</label>
            <input type="text" name="name" style={styles.input} value={formData.name} onChange={handleChange} />
          </div>
          <div style={styles.formGroup}>
            <label htmlFor="phone" style={styles.label}>Phone Number</label>
            <input type="tel" name="phone" style={styles.input} value={formData.phone} onChange={handleChange} />
          </div>
          <div style={styles.formGroup}>
            <label htmlFor="date" style={styles.label}>Preferred Date</label>
            <input type="date" name="date" style={styles.input} value={formData.date} onChange={handleChange} />
          </div>
          <div style={styles.formGroup}>
            <label htmlFor="message" style={styles.label}>Reason for Appointment</label>
            <textarea name="message" rows="4" style={styles.textarea} value={formData.message} onChange={handleChange}></textarea>
          </div>
          <button type="submit" style={styles.button}>Submit Appointment</button>
        </form>
      </div>
    </section>
  );
};

//=========== FOOTER COMPONENT ===========//
const Footer = () => (
  <footer style={styles.footer}>
    <div style={styles.container}>
      <div style={{ marginBottom: '16px' }}>
        <a href="#home" style={styles.footerLink}>Home</a>
        <a href="#about" style={styles.footerLink}>About Us</a>
        <a href="#services" style={styles.footerLink}>Services</a>
        <a href="#contact" style={styles.footerLink}>Contact Us</a>
        <a href="#terms" style={styles.footerLink}>Terms and Conditions</a>
      </div>
      <p>&copy; {new Date().getFullYear()} Dietitian Pradeepa's Clinic. All Rights Reserved.</p>
    </div>
  </footer>
);

//=========== MAIN APP COMPONENT ===========//
function App() {
  return (
    <div>
      <Header />
      <main>
        <Hero />
        <AppointmentForm />
      </main>
      <Footer />
    </div>
  );
}

export default App;
